    })

    docsButton.addEventListener('click', () => {
        sidebarContainer.classList.add('mobile-hidden')
        article.classList.remove('mobile-hidden')
        menuButton.setAttribute('variant-', 'background1')
        docsButton.setAttribute('variant-', '')
    })
</script>

