<style is:global>
    @import './Doc.css';
</style>

<Layout>
    <column self-="grow">
        <Navbar />
        <row self-="grow" gap-="1">
            <div id="sidebar-container" class="mobile-hidden">
                <Sidebar />
            </div>
            <div id="sidebar-resizer" aria-hidden="true"></div>
            <article id="doc-article" box-="square" shear-="top">
                <header is-="row" align-="between">
                    <div is-="badge" variant-="background0">
                        <h1>{frontmatter.title}</h1>
                    </div>
                </header>
                <row gap-="1" self-="grow">
                    <div id="scroll-container">
                        <main id="main-content">
                            <span
                                id="toc-page-title"
                                aria-hidden="true"
                                tabindex="-1"></span>
                            <slot />
                            <div id="doc-pagination">
                                {
                                    prevDoc && (
                                        <a
                                            href={`/${prevDoc.id}`}
                                            class="prev"
                                            box-="round"
                                            shear-="top"
                                            tabindex="0">
                                            <div is-="typography-block">
                                                <span
                                                    is-="badge"
                                                    variant-="background0">
                                                    <row gap-="1">
                                                        <span>←</span>
                                                        <code>&lt;C-b&gt;</code>
                                                        <span>Previous</span>
                                                    </row>
                                                </span>
                                            </div>
                                            <span pad-="1 0">
                                                {prevDoc.id.split('/')[0]}/
                                                {prevDoc.data.title}
                                            </span>
                                        </a>
                                    )
                                }
                                {
                                    nextDoc && (
                                        <a
                                            href={`/${nextDoc.id}`}
                                            class="next"
                                            box-="round"
                                            shear-="top"
                                            tabindex="0">
                                            <row
                                                align-="start end"
                                                is-="typography-block">
                                                <span
                                                    is-="badge"
                                                    variant-="background0">
                                                    <row gap-="1">
                                                        <span>Next</span>
                                                        <code>&lt;C-n&gt;</code>
                                                        <span>→</span>
                                                    </row>
                                                </span>
                                            </row>
                                            <span pad-="1 0">
                                                {nextDoc.id.split('/')[0]}/
                                                {nextDoc.data.title}
                                            </span>
                                        </a>
                                    )
                                }
                            </div>
                        </main>
                    </div>
                </row>
