    #vim-navigation-container {
        position: fixed;
        top: 1lh;
        right: 2ch;
    }

    #statusline {
        position: fixed;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 2lh;
        z-index: 100;
        background-color: var(--background1);
        /* box-shadow: 0 -1lh 0 0 var(--background1); */
    }

    #statusline [is-~='badge'][variant-='background0'] {
        --badge-color: var(--mantle);
        --badge-text: var(--foreground1);
    }

    #statusline [is-~='badge'][variant-='background1'] {
        --badge-color: var(--crust);
        --badge-text: var(--foreground0);
    }

    @media (max-width: 50ch) {
        #statusline-right {
            display: none;
        }
    }

    main {
        height: 100vh;
        scroll-snap-type: y mandatory;
        display: flex;
        flex-direction: column;
        overflow-y: auto;
        overflow-x: hidden;
        scrollbar-width: thin;
        scrollbar-color: var(--foreground1) var(--background2);
        padding-bottom: 2lh;
    }

    section,
    header {
        scroll-snap-align: start;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
    }

    section .content {
        max-width: 80ch;
        width: round(calc(100% - 2ch), 1ch);
        row-gap: 2ch;
        column-gap: 1lh;
    }

    @media (max-width: 1000px) {
        section .content {
            flex-direction: column-reverse;
        }
    }
</style>

